// Arma la petición a Nova Lite. Solo recibe datos pedagógicos y SIN nombre: la IA reescribe, no decide ni inventa.
const b = $input.first().json.body || $input.first().json;
const SISTEMA = "Eres un redactor para colegios de Ecuador. Reescribes un informe de acompañamiento escolar para que lo entienda una persona sin conocimientos técnicos (un docente, un padre o una madre). Reglas: frases cortas y claras, español de Ecuador, tono cálido y respetuoso, sin jerga (no digas 'riesgo relativo', 'SHAP', 'modelo', 'puntaje'). NO inventes datos ni cifras: usa solo las que te doy. No hagas diagnósticos ni culpes a la familia ni al estudiante. No menciones dinero, pensiones ni pagos. Di 'el estudiante' o 'la estudiante' como 'esta persona', sin nombre. Responde SOLO un JSON válido con esta forma: {\"resumen\":\"2 frases: quién es y qué pasa\",\"que_pasa\":[\"hasta 3 frases cortas, una por problema\"],\"que_hacer\":[\"hasta 3 frases cortas con la acción, quién la hace y cuándo\"]}";
const datos = JSON.stringify(b.informe);
return [{json:{req:{system:[{text:SISTEMA}],messages:[{role:'user',content:[{text:'Datos del informe (JSON):\n'+datos}]}],inferenceConfig:{maxTokens:700,temperature:0.2}}}}];

// Extrae el JSON de la respuesta. Si no es válido, se devuelve error y la API usa el texto original.
const it = $input.first().json;
try {
  if (it.error) throw new Error('AWS: ' + (it.error.message || it.error));
  let t = (it.output?.message?.content || []).map(c => c.text || '').join('').trim();
  t = t.replace(/^```json\s*|^```\s*|```$/g, '').trim();
  const j = JSON.parse(t);
  const arr = (a) => (Array.isArray(a) ? a : []).map(x => String(x).trim()).filter(Boolean).slice(0, 3);
  return [{json:{ok:true, resumen:String(j.resumen||'').trim(), que_pasa:arr(j.que_pasa), que_hacer:arr(j.que_hacer)}}];
} catch (e) { return [{json:{ok:false, error:String(e.message||e).slice(0,200)}}]; }
